package com.company.workflowbuilder.entity.data;
import com.company.workflowbuilder.entity.user.User; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="data_pipeline_files") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class PipelineFileVersion { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="pipeline_id",nullable=false) private DataPipeline pipeline; @Column(name="source_alias",nullable=false) private String sourceAlias; @Column(name="version_number",nullable=false) private int versionNumber; @Column(name="original_name",nullable=false) private String originalName; @Column(name="content_type") private String contentType; @Column(name="content_bytes",nullable=false,columnDefinition="bytea") private byte[] contentBytes; @Column(nullable=false,length=64) private String checksum; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="uploaded_by",nullable=false) private User uploadedBy; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; }
